class Solution:
    def minPathSum(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dp = [[0] * n for _ in range(m)]
        for row in range(m):
            dp[row][0] = grid[row][0]
        for col in range(n):
            dp[0][col] = grid[0][col]

        for row in range(1, m):
            for col in range(1, n):
                dp[row][col] = grid[row][col] + min(dp[row - 1][col], dp[row][col - 1])
        return dp[-1][-1]
